//! The plugin's own values: what a call looks for, what the service answers, and what goes wrong.
//!
//! The contract's types live in the private `bindings` module, generated by `wit-bindgen`; these mirror the part of
//! them the plugin uses, so the readers, the tests and the fuzz targets can name them. They become the contract's
//! types only at the boundary, in `lib.rs`.

use std::time::Duration;

/// A song as the service lists it, in a search or in a radio queue.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
#[non_exhaustive]
pub struct Song {
    /// The service's video id, the song's id for the contract.
    pub id: String,
    /// The title, as the service writes it.
    pub title: String,
    /// The artists the service links to, in its order.
    pub artists: Vec<Link>,
    /// The album the service links to, if any.
    pub album: Option<Link>,
    /// The length the service shows, if any.
    pub length: Option<Duration>,
    /// The thumbnails the service gives, `https` only.
    pub artwork: Vec<Thumbnail>,
}

/// An artist or an album the service links to.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
#[non_exhaustive]
pub struct Link {
    /// The service's browse id.
    pub id: String,
    /// The name or title, as the service writes it.
    pub name: String,
}

/// One size of a song's artwork.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
#[non_exhaustive]
pub struct Thumbnail {
    /// An `https` URL.
    pub url: String,
    /// The width in pixels, if the service gives it.
    pub width: Option<u32>,
    /// The height in pixels, if the service gives it.
    pub height: Option<u32>,
}

/// The track a call looks for on the service; it may come from any plugin, so only what any track has is used.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
#[non_exhaustive]
pub struct Wanted {
    /// The title.
    pub title: String,
    /// The artists' names.
    pub artists: Vec<String>,
    /// The length, if known.
    pub length: Option<Duration>,
    /// The ISRC, if known.
    pub isrc: Option<String>,
}

/// What can go wrong in a call; each one is the contract's error of the same name.
#[derive(Clone, Debug, PartialEq, Eq)]
#[non_exhaustive]
pub enum Error {
    /// The service has no song matching the track.
    NotFound,
    /// The service asked to wait, for the delay it gave if it gave one.
    RateLimited(Option<Duration>),
    /// The call's arguments cannot be asked of the service.
    InvalidInput(String),
    /// The service failed, could not be reached, or answered something the plugin cannot read.
    Upstream(String),
}

/// A request to the service: always a `POST` of a JSON body.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
#[non_exhaustive]
pub struct Request {
    /// An `https` URL on the declared host.
    pub url: String,
    /// The headers, in order.
    pub headers: Vec<(String, String)>,
    /// The JSON body.
    pub body: Vec<u8>,
}

/// A response from the service, as the host returns it.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
#[non_exhaustive]
pub struct Response {
    /// The HTTP status.
    pub status: u16,
    /// The headers, as received.
    pub headers: Vec<(String, String)>,
    /// The body.
    pub body: Vec<u8>,
}

impl Response {
    /// A response with this status, headers and body; the fuzz targets build theirs with it.
    ///
    /// ```
    /// use vehicoule_plugin_ytmusic::model::Response;
    ///
    /// let response = Response::new(200, Vec::new(), b"{}".to_vec());
    /// assert_eq!(response.status, 200);
    /// ```
    #[must_use]
    pub fn new(status: u16, headers: Vec<(String, String)>, body: Vec<u8>) -> Self {
        Self {
            status,
            headers,
            body,
        }
    }
}
